const canvas = document.getElementById('graph-canvas');
        const ctx = canvas.getContext('2d');
        let dataPoints = [];
        const MAX_POINTS = 200;
        let audioContext = null;
        let audioEnabled = false;
        let lastClickTime = 0;
        // Gamification Variables
        let stabilityScore = 0;
        let stabilityProgress = 0;
        const ringCircle = document.getElementById('stability-progress');
        const circumference = 36 * 2 * Math.PI;
        ringCircle.style.strokeDasharray = `${circumference} ${circumference}`;
        // Status Elements
        const scanStatusEl = document.getElementById('scan-status');
        const pollRateEl = document.getElementById('poll-rate');
        const sensorLight = document.getElementById('sensor-light');
        const sensorText = document.getElementById('sensor-text');
        let lastTimestamp = 0;
        function requestAccess() {
            if (typeof DeviceMotionEvent.requestPermission === 'function') {
                DeviceMotionEvent.requestPermission()
                    .then(permissionState => {
                        if (permissionState === 'granted') {
                            startLogging();
                        }
                    })
                    .catch(console.error);
            } else {
                startLogging();
            }
        }
        function startLogging() {
            document.getElementById('permission-request').classList.add('hidden');
            const ui = document.getElementById('instrument-ui');
            ui.classList.remove('hidden');
            setTimeout(() => ui.classList.add('opacity-100'), 50);
            // Update Telemetry Panel
            scanStatusEl.innerText = "ACTIVE";
            scanStatusEl.classList.add('text-emerald-500');
            sensorLight.classList.remove('bg-slate-300');
            sensorLight.classList.add('bg-emerald-500', 'animate-pulse');
            sensorText.innerText = "Receiving";
            window.addEventListener('devicemotion', handleMotion);
            // Setup Audio Context for clicks
            if (!audioContext) audioContext = new (window.AudioContext || window.webkitAudioContext)();
        }
        function handleMotion(event) {
            const acc = event.accelerationIncludingGravity;
            const rot = event.rotationRate;
            // Calculate polling rate roughly
            const now = performance.now();
            if (lastTimestamp) {
                const delta = now - lastTimestamp;
                pollRateEl.innerText = Math.round(1000 / delta) + "Hz";
            }
            lastTimestamp = now;
            // Update Accelerometer DOM
            updateDOM('acc-x', acc.x);
            updateDOM('acc-y', acc.y);
            updateDOM('acc-z', acc.z);
            // Update Gyroscope DOM
            updateDOM('gyro-a', rot.alpha);
            updateDOM('gyro-b', rot.beta);
            updateDOM('gyro-g', rot.gamma);
            // Store for graph
            dataPoints.push({ x: acc.x, y: acc.y, z: acc.z });
            if (dataPoints.length > MAX_POINTS) dataPoints.shift();
            drawGraph();
            updateGame(acc);
            processAudio(acc);
        }
        function updateDOM(id, val) {
            const el = document.getElementById(id);
            if (el) el.innerText = val ? val.toFixed(2) : "0.00";
        }
        function drawGraph() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            // Draw grid line (zero)
            ctx.strokeStyle = '#1e293b';
            ctx.setLineDash([5, 5]);
            ctx.beginPath();
            ctx.moveTo(0, canvas.height / 2);
            ctx.lineTo(canvas.width, canvas.height / 2);
            ctx.stroke();
            ctx.setLineDash([]);
            const drawAxis = (key, color) => {
                ctx.strokeStyle = color;
                ctx.lineWidth = 3;
                ctx.beginPath();
                dataPoints.forEach((p, i) => {
                    const xPos = (i / MAX_POINTS) * canvas.width;
                    const yPos = (canvas.height / 2) - (p[key] * 5);
                    if (i === 0) ctx.moveTo(xPos, yPos);
                    else ctx.lineTo(xPos, yPos);
                });
                ctx.stroke();
            };
            drawAxis('x', '#ef4444');
            drawAxis('y', '#22c55e');
            drawAxis('z', '#3b82f6');
        }
        // --- Gamification Logic ---
        function updateGame(acc) {
            // Calculate jitter magnitude (excluding gravity Z roughly by checking deviation from 9.8 or simple delta)
            // Simplified jitter: |x| + |y| + |z-9.8|
            const jitter = Math.abs(acc.x) + Math.abs(acc.y) + Math.abs(acc.z - 9.81);
            document.getElementById('jitter-val').innerText = jitter.toFixed(2);
            const jitterPercent = Math.min((jitter / 2.0) * 100, 100);
            document.getElementById('jitter-bar').style.width = jitterPercent + "%";
            // Game State
            if (jitter < 0.20) {
                stabilityProgress = Math.min(stabilityProgress + 0.5, 100);
                document.getElementById('jitter-bar').classList.remove('bg-red-500');
                document.getElementById('jitter-bar').classList.add('bg-emerald-500');
            } else {
                stabilityProgress = Math.max(stabilityProgress - 2.0, 0);
                document.getElementById('jitter-bar').classList.add('bg-red-500');
                document.getElementById('jitter-bar').classList.remove('bg-emerald-500');
            }
            // Update Ring
            const offset = circumference - (stabilityProgress / 100) * circumference;
            ringCircle.style.strokeDashoffset = offset;
            document.getElementById('stability-score').innerText = Math.floor(stabilityProgress) + "%";
            // Tiers
            const tierEl = document.getElementById('game-tier');
            const msgEl = document.getElementById('feedback-msg');
            if (stabilityProgress > 95) {
                tierEl.innerText = "SNIPER ELITE";
                tierEl.className = "text-xl font-black text-emerald-400 level-badge-anim";
                msgEl.style.opacity = 1;
            } else if (stabilityProgress > 75) {
                tierEl.innerText = "SURGEON";
                tierEl.className = "text-xl font-black text-blue-400";
                msgEl.style.opacity = 0;
            } else if (stabilityProgress > 50) {
                tierEl.innerText = "STEADY";
                tierEl.className = "text-xl font-black text-yellow-400";
                msgEl.style.opacity = 0;
            } else {
                tierEl.innerText = "UNSTABLE";
                tierEl.className = "text-xl font-black text-slate-500";
                msgEl.style.opacity = 0;
            }
        }
        // --- Audio Logic ---
        function toggleAudio() {
            audioEnabled = !audioEnabled;
            const btn = document.getElementById('audio-btn');
            if (audioEnabled) {
                btn.classList.add('text-orange-500', 'border-orange-500');
                if (audioContext && audioContext.state === 'suspended') audioContext.resume();
            } else {
                btn.classList.remove('text-orange-500', 'border-orange-500');
            }
        }
        function processAudio(acc) {
            if (!audioEnabled || !audioContext) return;
            // Create geiger counter clicks based on movement
            const motion = Math.abs(acc.x) + Math.abs(acc.y) + Math.abs(acc.z - 9.8);
            const now = audioContext.currentTime;
            // Higher motion = shorter interval between clicks
            const interval = Math.max(0.05, 1 / (motion * 2));
            if (now - lastClickTime > interval) {
                playClick();
                lastClickTime = now;
            }
        }
        function playClick() {
            const osc = audioContext.createOscillator();
            const gain = audioContext.createGain();
            osc.connect(gain);
            gain.connect(audioContext.destination);
            osc.frequency.value = 800 + Math.random() * 200;
            osc.type = 'square';
            gain.gain.setValueAtTime(0.05, audioContext.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, audioContext.currentTime + 0.05);
            osc.start();
            osc.stop(audioContext.currentTime + 0.05);
        }
        function resetStats() {
            dataPoints = [];
            stabilityProgress = 0;
            ctx.clearRect(0, 0, canvas.width, canvas.height);
        }
        function loadSample() {
            // Simulated data
            if (dataPoints.length > 0) return;
            document.getElementById('permission-request').classList.add('hidden');
            const ui = document.getElementById('instrument-ui');
            ui.classList.remove('hidden');
            ui.classList.add('opacity-100');
            scanStatusEl.innerText = "SIMULATION";
            scanStatusEl.classList.add('text-blue-400');
            let counter = 0;
            setInterval(() => {
                const noise = () => (Math.random() - 0.5) * 0.5;
                const point = {
                    x: Math.sin(counter * 0.1) * 2 + noise(),
                    y: Math.cos(counter * 0.1) * 2 + noise(),
                    z: 9.8 + noise()
                };
                // Simulate Event Object for Game Logic
                const simEvent = {
                    accelerationIncludingGravity: point,
                    rotationRate: { alpha: noise() * 10, beta: noise() * 10, gamma: noise() * 10 }
                };
                updateDOM('acc-x', point.x);
                updateDOM('acc-y', point.y);
                updateDOM('acc-z', point.z);
                updateDOM('gyro-a', simEvent.rotationRate.alpha);
                updateDOM('gyro-b', simEvent.rotationRate.beta);
                updateDOM('gyro-g', simEvent.rotationRate.gamma);
                dataPoints.push(point);
                if (dataPoints.length > MAX_POINTS) dataPoints.shift();
                drawGraph();
                updateGame(point);
                counter++;
            }, 50);
        }
        // --- Interactive Tour ---
        const tourSteps = [
            { id: 'main-tool-section', text: 'This is your Control Center. It contains the raw sensor data and visualization tools.', pos: 'bottom' },
            { id: 'game-panel', text: 'Stability Challenge! Keep your device perfectly still to fill the green ring and achieve "Sniper Elite" status.', pos: 'bottom' },
            { id: 'accel-box', text: 'Linear Acceleration: This measures physical force (gravity + movement) in m/s².', pos: 'top' },
            { id: 'gyro-box', text: 'Gyroscope: This measures how fast you are rotating in degrees per second.', pos: 'top' },
            { id: 'graph-container', text: 'Oscilloscope: A real-time history of the last 200 data points. Watch for spikes!', pos: 'top' }
        ];
        let currentStep = 0;
        function startTour() {
            currentStep = 0;
            document.getElementById('tour-overlay').style.display = 'block';
            setTimeout(() => document.getElementById('tour-overlay').style.opacity = '1', 10);
            // Ensure UI is visible if locked
            if (document.getElementById('instrument-ui').classList.contains('hidden')) {
                loadSample(); // Force load for tutorial purposes
            }
            showStep();
        }
        function showStep() {
            // Clean up previous highlights
            document.querySelectorAll('.tour-highlight').forEach(el => {
                el.classList.remove('tour-highlight');
                el.style.zIndex = '';
            });
            document.querySelectorAll('.tour-tooltip').forEach(el => el.remove());
            if (currentStep >= tourSteps.length) {
                endTour();
                return;
            }
            const step = tourSteps[currentStep];
            const el = document.getElementById(step.id);
            if (!el) { currentStep++; showStep(); return; }
            el.scrollIntoView({ behavior: 'smooth', block: 'center' });
            el.classList.add('tour-highlight');
            // Create Tooltip
            const rect = el.getBoundingClientRect();
            const tooltip = document.createElement('div');
            tooltip.className = 'tour-tooltip';
            tooltip.innerHTML = `
                <h4 class="font-bold text-slate-800 text-sm mb-2">Step ${currentStep + 1}/${tourSteps.length}</h4>
                <p class="text-xs text-slate-600 mb-3 leading-relaxed">${step.text}</p>
                <div class="flex justify-between">
                    <button onclick="endTour()" class="text-xs text-slate-400 underline">Skip</button>
                    <button onclick="nextStep()" class="bg-[#EE6C4D] text-white text-xs font-bold px-3 py-1 rounded-md shadow-sm">Next</button>
                </div>
            `;
            // Position Logic
            let top, left;
            if (step.pos === 'top') {
                top = rect.top - 140;
                left = rect.left;
            } else {
                top = rect.bottom + 20;
                left = rect.left;
            }
            // Boundary checks
            if (left + 280 > window.innerWidth) left = window.innerWidth - 300;
            if (left < 10) left = 10;
            tooltip.style.top = (top + window.scrollY) + 'px';
            tooltip.style.left = left + 'px';
            document.body.appendChild(tooltip);
        }
        function nextStep() {
            currentStep++;
            showStep();
        }
        function endTour() {
            document.getElementById('tour-overlay').style.opacity = '0';
            setTimeout(() => {
                document.getElementById('tour-overlay').style.display = 'none';
                document.querySelectorAll('.tour-highlight').forEach(el => el.classList.remove('tour-highlight'));
                document.querySelectorAll('.tour-tooltip').forEach(el => el.remove());
            }, 300);
        }
        // Setup canvas sizing
        function resize() {
            canvas.width = canvas.offsetWidth;
            canvas.height = canvas.offsetHeight;
        }
        window.addEventListener('resize', resize);
        resize();
        // Scroll to Top Logic
